from collections import defaultdict
class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        best = defaultdict(lambda: float('inf'))
        ans, p = float('-inf'), 0
        for x in nums:
            p += x
            for y in (x - k, x + k):
                if y in best:
                    ans = max(ans, p - best[y])
            if p < best[x]:
                best[x] = p
        return ans if ans != float('-inf') else 0

