class Solution {
public:
    long long maximumSubarraySum(vector<int>& nums, int k) {
        unordered_map<long long,long long> best;
        long long ans = LLONG_MIN, p = 0;
        for (int x : nums) {
            p += x;
            auto it = best.find((long long)x - k);
            if (it != best.end()) ans = max(ans, p - it->second);
            it = best.find((long long)x + k);
            if (it != best.end()) ans = max(ans, p - it->second);
            auto &b = best[x];
            if (p < b) b = p;
        }
        return ans == LLONG_MIN ? 0 : ans;
    }
};

