class Solution {
    public long maximumSubarraySum(int[] nums, int k) {
        Map<Long, Long> best = new HashMap<>();
        long ans = Long.MIN_VALUE, p = 0;
        for (int x : nums) {
            p += x;
            Long a = best.get((long)x - k), b = best.get((long)x + k);
            if (a != null) ans = Math.max(ans, p - a);
            if (b != null) ans = Math.max(ans, p - b);
            best.merge((long)x, p, Math::min);
        }
        return ans == Long.MIN_VALUE ? 0 : ans;
    }
}

