var maximumSubarraySum = function(nums, k) {
    const best = new Map();
    let ans = -Infinity, p = 0;
    for (const x of nums) {
        p += x;
        for (const y of [x - k, x + k]) {
            if (best.has(y)) ans = Math.max(ans, p - best.get(y));
        }
        const cur = best.get(x);
        if (cur === undefined || p < cur) best.set(x, p);
    }
    return ans === -Infinity ? 0 : ans;
};
